    .search-input:focus-visible {
      outline: none;
      border-color: var(--focus);
      box-shadow: 0 0 0 4px var(--focus-ring);
    }

    .search-btn {
      position: absolute;
      right: 0.35rem;
      top: 0.35rem;
      bottom: 0.35rem;
      width: 2.5rem;
      border: none;
      border-radius: 0.55rem;
      background: transparent;
      color: #62727d;
      cursor: pointer;
    }

    .search-btn:hover {
      background: #f0f4f6;
      color: var(--focus);
    }

    .search-btn:focus-visible {
      outline: none;
      box-shadow: 0 0 0 4px var(--focus-ring);
    }

    .error-band {
      margin: 0.35rem auto 0;
      width: min(100%, 560px);
      padding: 0.8rem 1rem;
      border-radius: 0.55rem;
      background: var(--surface-muted);
      color: #69727a;
      font-size: 0.95rem;
      font-weight: 500;
      letter-spacing: 0.01em;
    }

    .divider {
      margin: 0.3rem auto 0;
      width: min(100%, 560px);
      border: 0;
      height: 1px;
      background: var(--divider);
    }

    h2 {
      margin: 0.45rem 0 0.15rem;
      font-size: 1.14rem;
      font-weight: 600;
      letter-spacing: -0.01em;
    }

    .links {
      display: flex;
      flex-direction: column;
      gap: 0.58rem;
      align-items: center;
    }

    .links a {
      color: var(--text-link);
      text-decoration-thickness: 1px;
      text-underline-offset: 3px;
      font-weight: 500;
    }

    .links a:hover,
    .links a:focus-visible {
      color: #595959;
    }

    .cookie-banner {
      position: fixed;
      left: 0;
      right: 0;
      bottom: 0;
      z-index: 20;
      border-top: 1px solid var(--divider);
      background: rgba(255, 255, 255, 0.97);
      backdrop-filter: blur(7px);
      padding: 0.8rem 1rem;
    }

    .cookie-inner {
      width: min(100%, 1000px);
      margin: 0 auto;
      display: flex;
      gap: 0.9rem;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
    }

    .cookie-text {
      margin: 0;
      color: #555f67;
      font-size: 0.9rem;
      line-height: 1.5;
      max-width: 82ch;
    }

    .cookie-text a {
      color: #5c6870;
    }

    .manage-btn,
    .modal-btn {
      border: 1px solid #b7c3ca;
      background: #fff;
      color: #334046;
      border-radius: 0.5rem;
      font-weight: 600;
      padding: 0.62rem 0.95rem;
      cursor: pointer;
    }

    .manage-btn:hover,
    .modal-btn:hover {
      border-color: #96aab4;
      background: #f7fafb;
    }

    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(18, 18, 18, 0.35);
      display: none;
      place-items: center;
      padding: 1rem;
      z-index: 40;
    }

    .modal-overlay[aria-hidden="false"] {
      display: grid;
    }

    .modal {
      width: min(100%, 560px);
      background: #fff;
      border-radius: 0.9rem;
      box-shadow: var(--shadow);
      padding: 1.2rem;
