      top: 0.08rem;
      left: 0.1rem;
      transition: transform 0.2s ease;
      box-shadow: 0 1px 2px rgba(0, 0, 0, 0.18);
    }

    .switch:checked {
      background: #5f7d88;
      border-color: #5f7d88;
    }

    .switch:checked::after {
      transform: translateX(1.3rem);
    }

    .modal-actions {
      margin-top: 1.1rem;
      display: flex;
      justify-content: flex-end;
      gap: 0.55rem;
    }

    .modal-btn.primary {
      background: #1f3e47;
      border-color: #1f3e47;
      color: #fff;
    }

    .modal-btn.primary:hover {
      background: #173038;
    }

    @media (max-width: 640px) {
      .page {
        padding-top: 2.2rem;
      }

      .cookie-inner {
        align-items: flex-start;
      }

      .manage-btn {
        width: 100%;
      }

      .modal-actions {
        flex-direction: column-reverse;
      }

      .modal-btn {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="page">
    <section class="stack" aria-labelledby="error-title">
      <div class="logo" aria-label="IdeaForum logo">
        ID<span class="missing-e" aria-hidden="true"></span>AFORUM
      </div>

      <h1 id="error-title">Sorry, we can't find that.</h1>
      <p class="lead">Perhaps we can help you find the content you're looking for:</p>

      <form class="search-wrap" id="search-form" role="search" aria-label="Search IdeaForum">
        <input class="search-input" id="search-query" name="q" type="search" placeholder="Search IdeaForum..." autocomplete="off" required />
        <button class="search-btn" type="submit" aria-label="Search">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path d="M11 4a7 7 0 1 0 0 14a7 7 0 0 0 0-14Zm0 0l8 8" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
            <path d="m20 20-3.8-3.8" stroke="currentColor" stroke-width="2" stroke-linecap="round" />
          </svg>
        </button>
      </form>

      <div class="error-band" aria-live="polite">HTTP Error 404</div>
      <hr class="divider" />

      <h2>What's next?</h2>
      <nav class="links" aria-label="Recovery navigation">
        <a href="./">Go to the homepage</a>
        <a href="./help-desk.html">Visit our Help Desk</a>
      </nav>
    </section>
  </main>

  <aside class="cookie-banner" id="cookie-banner" aria-label="Cookie consent">
    <div class="cookie-inner">
      <p class="cookie-text">
        This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics, personalization, and targeted advertising. To learn more, view the following link:
        <a href="./privacy-policy.html" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
      </p>
      <button class="manage-btn" id="manage-preferences" type="button">Manage Preferences</button>
    </div>
  </aside>

  <div class="modal-overlay" id="preferences-modal" aria-hidden="true">
    <section class="modal" role="dialog" aria-modal="true" aria-labelledby="pref-title" aria-describedby="pref-description">
      <h3 id="pref-title">Cookie Preferences</h3>
      <p id="pref-description">Adjust how IdeaForum uses cookies and related technologies. Essential cookies are always active to keep the site secure and functional.</p>

      <label class="pref-row" for="pref-essential">
        <span>Essential cookies (always on)</span>
        <input class="switch" id="pref-essential" type="checkbox" checked disabled />
      </label>
      <label class="pref-row" for="pref-analytics">
        <span>Analytics cookies</span>
        <input class="switch" id="pref-analytics" type="checkbox" checked />
      </label>
      <label class="pref-row" for="pref-personalization">
        <span>Personalization cookies</span>
        <input class="switch" id="pref-personalization" type="checkbox" />
      </label>
      <label class="pref-row" for="pref-advertising">
        <span>Targeted advertising cookies</span>
        <input class="switch" id="pref-advertising" type="checkbox" />
      </label>

      <div class="modal-actions">
        <button class="modal-btn" id="cancel-preferences" type="button">Cancel</button>
        <button class="modal-btn primary" id="save-preferences" type="button">Save Preferences</button>
      </div>
    </section>
  </div>

  <script>
    (function () {
      const searchForm = document.getElementById('search-form');
      const searchInput = document.getElementById('search-query');
      const manageButton = document.getElementById('manage-preferences');
      const modal = document.getElementById('preferences-modal');
      const cancelButton = document.getElementById('cancel-preferences');
      const saveButton = document.getElementById('save-preferences');

      searchForm.addEventListener('submit', function (event) {
        event.preventDefault();
        const query = searchInput.value.trim();
        if (!query) return;
        const destination = './search.html?q=' + encodeURIComponent(query);
        window.location.href = destination;
      });

      function openModal() {
        modal.setAttribute('aria-hidden', 'false');
        document.body.style.overflow = 'hidden';
      }

      function closeModal() {
        modal.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
      }

      manageButton.addEventListener('click', openModal);
      cancelButton.addEventListener('click', closeModal);
      saveButton.addEventListener('click', function () {
        closeModal();
        localStorage.setItem('ideaforum-cookie-preferences', JSON.stringify({
          analytics: document.getElementById('pref-analytics').checked,
          personalization: document.getElementById('pref-personalization').checked,
          advertising: document.getElementById('pref-advertising').checked,
          savedAt: new Date().toISOString()
        }));
      });

      modal.addEventListener('click', function (event) {
        if (event.target === modal) closeModal();
      });

      document.addEventListener('keydown', function (event) {
        if (event.key === 'Escape' && modal.getAttribute('aria-hidden') === 'false') {
          closeModal();
        }
      });

      try {
        const stored = localStorage.getItem('ideaforum-cookie-preferences');
        if (stored) {
          const parsed = JSON.parse(stored);
          if (typeof parsed.analytics === 'boolean') document.getElementById('pref-analytics').checked = parsed.analytics;
          if (typeof parsed.personalization === 'boolean') document.getElementById('pref-personalization').checked = parsed.personalization;
          if (typeof parsed.advertising === 'boolean') document.getElementById('pref-advertising').checked = parsed.advertising;
        }
      } catch (error) {
      }
    })();
  </script>
</body>
</html>
